<?php $title='Dashboard'; require __DIR__.'/partials/top.php';
$tid=(int)$_SESSION['user']['tenant_id'];$pdo=appDb();$k=['active'=>0,'unassigned'=>0,'resolved'=>0,'first'=>'—'];$recent=[];$channels=[];$days=array_fill(0,7,0);
try{$q=$pdo->prepare("SELECT COUNT(*) FROM conversations WHERE tenant_id=? AND status IN ('open','pending')");$q->execute([$tid]);$k['active']=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM conversations WHERE tenant_id=? AND status IN ('open','pending') AND assigned_user_id IS NULL");$q->execute([$tid]);$k['unassigned']=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM conversations WHERE tenant_id=? AND status='resolved' AND DATE(last_message_at)=CURDATE()");$q->execute([$tid]);$k['resolved']=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT c.id,c.status,c.assigned_user_id,c.last_message_at,ct.name client,ch.type,u.name agent FROM conversations c JOIN contacts ct ON ct.id=c.contact_id JOIN channels ch ON ch.id=c.channel_id LEFT JOIN users u ON u.id=c.assigned_user_id WHERE c.tenant_id=? AND c.status IN ('open','pending') ORDER BY COALESCE(c.last_message_at,c.created_at) ASC LIMIT 20");$q->execute([$tid]);$recent=$q->fetchAll();$q=$pdo->prepare('SELECT type,name,status,last_event_at FROM channels WHERE tenant_id=? ORDER BY type');$q->execute([$tid]);$channels=$q->fetchAll();$q=$pdo->prepare("SELECT DATE(sent_at) d,COUNT(*) n FROM messages WHERE tenant_id=? AND sent_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(sent_at)");$q->execute([$tid]);$map=[];foreach($q->fetchAll() as $r)$map[$r['d']]=(int)$r['n'];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$days[6-$i]=$map[$d]??0;}}catch(Throwable $e){}
try{$q=$pdo->prepare("SELECT AVG(TIMESTAMPDIFF(SECOND,m1.sent_at,(SELECT MIN(m2.sent_at) FROM messages m2 WHERE m2.tenant_id=m1.tenant_id AND m2.conversation_id=m1.conversation_id AND m2.direction='out' AND m2.sent_at>=m1.sent_at))) avg_seconds FROM messages m1 WHERE m1.tenant_id=? AND m1.direction='in' AND m1.sent_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)");$q->execute([$tid]);$sec=$q->fetchColumn();if($sec!==null){$sec=(int)round($sec);$k['first']=$sec<60?$sec.' s':($sec<3600?round($sec/60).' min':round($sec/3600,1).' h');}}catch(Throwable $e){}
$max=max(1,...$days); ?>
<section class="welcome"><div><small>RESUMEN OPERATIVO</small><h1>Bienvenido de nuevo, <?=htmlspecialchars(explode(' ',trim($_SESSION['user']['name']))[0])?></h1><p>Actividad omnicanal de <?=htmlspecialchars($_SESSION['user']['company'])?>.</p></div><button class="soft" onclick="location.reload()"><i class="fa-solid fa-rotate"></i> Actualizar</button></section>
<section class="kpis premium-kpis"><article><span class="kpi-icon"><i class="fa-solid fa-comments"></i></span><div><span>Chats activos</span><b><?=$k['active']?></b><small>Conversaciones abiertas</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-user-clock"></i></span><div><span>Sin asignar</span><b><?=$k['unassigned']?></b><small>Requieren atención</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-circle-check"></i></span><div><span>Resueltos hoy</span><b><?=$k['resolved']?></b><small>Datos reales del tenant</small></div></article><article><span class="kpi-icon"><i class="fa-solid fa-stopwatch"></i></span><div><span>Primera respuesta</span><b><?=$k['first']?></b><small>Promedio real · últimos 7 días</small></div></article></section>
<section class="grid2 dashboard-grid"><article class="panel chart-card"><div class="panel-head"><div><b><i class="fa-solid fa-chart-column"></i> Actividad de mensajes</b><small>Últimos 7 días</small></div></div><div class="bars"><?php foreach($days as $i=>$n):?><div class="bar-wrap"><span class="bar-value"><?=$n?></span><div class="bar" style="height:<?=max(4,round($n/$max*100))?>%"></div><small><?=['L','M','X','J','V','S','D'][date('N',strtotime('-'.(6-$i).' days'))-1]?></small></div><?php endforeach?></div></article><article class="panel"><div class="panel-head"><div><b><i class="fa-solid fa-signal"></i> Canales</b><small>Estado real configurado</small></div></div><?php if(!$channels):?><div class="empty-compact"><i class="fa-solid fa-link-slash"></i><b>Sin canales configurados</b><a href="?page=channels">Configurar canales</a></div><?php else:foreach($channels as $c):?><div class="source"><b><?=htmlspecialchars(ucfirst($c['type']).' · '.$c['name'])?></b><span class="status <?=$c['status']==='connected'?'ok':''?>"><?=htmlspecialchars($c['status'])?></span></div><?php endforeach;endif?></article></section>
<section class="panel"><div class="panel-head"><div><b>Conversaciones que requieren atención</b><small>Información real, sin datos de demostración</small></div><a href="?page=inbox">Abrir bandeja <i class="fa-solid fa-arrow-right"></i></a></div><div class="record-toolbar"><label>Mostrar <select class="select2 compact"><option>10</option><option>25</option><option>50</option></select> registros</label><div class="search-wrap"><i class="fa-solid fa-magnifying-glass"></i><input class="list-search" placeholder="Buscar conversación…"><button class="clear-search" hidden><i class="fa-solid fa-xmark"></i></button></div></div><div class="responsive-records"><?php if(!$recent):?><div class="empty-compact"><i class="fa-regular fa-comments"></i><b>No hay conversaciones pendientes</b><span>Cuando entren mensajes aparecerán aquí.</span></div><?php else:foreach($recent as $r):?><article class="record-card searchable"><div><small>Cliente</small><b><?=htmlspecialchars($r['client']?:'Sin nombre')?></b></div><div><small>Canal</small><span><?=htmlspecialchars(ucfirst($r['type']))?></span></div><div><small>Asignado</small><span><?=htmlspecialchars($r['agent']?:'Sin asignar')?></span></div><a href="?page=inbox&conversation=<?=$r['id']?>"><i class="fa-solid fa-eye"></i> Ver detalle</a></article><?php endforeach;endif?></div></section>
<?php require __DIR__.'/partials/bottom.php'; ?>